 3 files changed, 70 insertions(+), 21 deletions(-)
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 168) #if defined(__linux__)
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 169) // Extracts the linker provided build ID from the PT_NOTE segment found in info.
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 170) //
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 171) // On failure, returns an empty string.
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 172) std::string GetBuildId(const dl_phdr_info* const info) {
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 173)   std::string result;
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 174)
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 175)   // pt_note contains entries (of type ElfW(Nhdr)) starting at
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 176)   //   info->dlpi_addr + pt_note->p_vaddr
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 177)   // with length
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 178)   //   pt_note->p_memsz
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 179)   //
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 180)   // The length of each entry is given by
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 181)   //   Align(sizeof(ElfW(Nhdr)) + nhdr->n_namesz) + Align(nhdr->n_descsz)
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 182)   for (int i = 0; i < info->dlpi_phnum; ++i) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 183)     const ElfW(Phdr)* pt_note = &info->dlpi_phdr[i];
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 184)     if (pt_note->p_type != PT_NOTE) continue;
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 185)
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 186)     const char* note =
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 187)         reinterpret_cast<char*>(info->dlpi_addr + pt_note->p_vaddr);
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 188)     const char* const last = note + pt_note->p_filesz;
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 189)     const ElfW(Word) align = pt_note->p_align;
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 190)     while (note < last) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 191)       const ElfW(Nhdr)* const nhdr = reinterpret_cast<const ElfW(Nhdr)*>(note);
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 192)       if (note + sizeof(*nhdr) > last) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 193)         // Corrupt PT_NOTE
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 194)         break;
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 195)       }
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 196)
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 197)       // Both the start and end of the descriptor are aligned by sh_addralign
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 198)       // (= p_align).
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 199)       const ElfW(Word) desc_start =
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 200)           (sizeof(*nhdr) + nhdr->n_namesz + align - 1) & -align;
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 201)       const ElfW(Word) size =
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 202)           desc_start + ((nhdr->n_descsz + align - 1) & -align);
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 203)
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 204)       // Beware of overflows / wrap-around.
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 205)       if (nhdr->n_namesz >= static_cast<ElfW(Word)>(-align) ||
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 206)           nhdr->n_descsz >= static_cast<ElfW(Word)>(-align) ||
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 207)           size < sizeof(*nhdr) || note + size > last) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 208)         // Corrupt PT_NOTE
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 209)         break;
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 210)       }
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 211)
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 212)       if (nhdr->n_type == NT_GNU_BUILD_ID) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 213)         const char* const note_name = note + sizeof(*nhdr);
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 214)         // n_namesz is the length of note_name.
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 215)         if (nhdr->n_namesz == 4 && memcmp(note_name, "GNU\0", 4) == 0) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 216)           if (!result.empty()) {
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 217)             // Repeated build-ids.  Ignore them.
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 218)             return "";
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 219)           }
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 220)           result = absl::BytesToHexString(
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 221)               absl::string_view(note + desc_start, nhdr->n_descsz));
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 222)         }
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 223)       }
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 224)       note += size;
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 225)     }
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 226)   }
c33cb2d8 (TCMalloc Team  2023-05-09 13:03:24 -0700 227)
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 228)   return result;
7c823385 (Chris Kennelly 2022-01-10 18:36:11 -0800 229) }
